-- DRAFT. Do not apply until database parameters, permissions and backup policy are approved.
-- IDs are generated by the application; no extensions or cluster configuration are required.
BEGIN;
CREATE SCHEMA tender_app;
CREATE TABLE tender_app.app_user (
 id uuid PRIMARY KEY, external_subject text NOT NULL UNIQUE,
 display_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE tender_app.tender (
 id uuid PRIMARY KEY, title text NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 300),
 created_by uuid NOT NULL REFERENCES tender_app.app_user(id),
 specification_skipped boolean NOT NULL DEFAULT false,
 revision integer NOT NULL DEFAULT 1 CHECK (revision > 0),
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE tender_app.specification_item (
 id uuid PRIMARY KEY, tender_id uuid NOT NULL REFERENCES tender_app.tender(id),
 position integer NOT NULL CHECK (position > 0), description text NOT NULL,
 quantity numeric(18,6) CHECK (quantity > 0), unit text,
 UNIQUE (tender_id, position)
);
CREATE TABLE tender_app.supplier (
 id uuid PRIMARY KEY, legal_name text NOT NULL, tax_id text, email text,
 verified_by uuid REFERENCES tender_app.app_user(id), verified_at timestamptz
);
CREATE TABLE tender_app.offer_package (
 id uuid PRIMARY KEY, tender_id uuid NOT NULL REFERENCES tender_app.tender(id),
 supplier_id uuid REFERENCES tender_app.supplier(id),
 created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (id, tender_id)
);
CREATE TABLE tender_app.blob (
 sha256 char(64) PRIMARY KEY CHECK (sha256 ~ '^[a-f0-9]{64}$'),
 storage_key text NOT NULL UNIQUE, byte_size bigint NOT NULL CHECK (byte_size > 0),
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE tender_app.document (
 id uuid PRIMARY KEY, tender_id uuid NOT NULL REFERENCES tender_app.tender(id),
 offer_package_id uuid, purpose text NOT NULL CHECK (purpose IN ('offer', 'specification')),
 original_name text NOT NULL, mime_type text NOT NULL,
 blob_sha256 char(64) NOT NULL REFERENCES tender_app.blob(sha256),
 status text NOT NULL DEFAULT 'uploaded' CHECK (status IN ('uploaded','recognized','review','confirmed','error')),
 revision integer NOT NULL DEFAULT 1 CHECK (revision > 0), error_code text,
 uploaded_by uuid NOT NULL REFERENCES tender_app.app_user(id),
 created_at timestamptz NOT NULL DEFAULT now(),
 FOREIGN KEY (offer_package_id, tender_id) REFERENCES tender_app.offer_package(id, tender_id),
 CHECK ((purpose = 'offer' AND offer_package_id IS NOT NULL) OR (purpose = 'specification' AND offer_package_id IS NULL)),
 UNIQUE (tender_id, blob_sha256, purpose)
);
CREATE TABLE tender_app.offer_version (
 id uuid PRIMARY KEY, offer_package_id uuid NOT NULL REFERENCES tender_app.offer_package(id),
 version integer NOT NULL CHECK (version > 0), price_minor bigint CHECK (price_minor >= 0),
 extra_cost_minor bigint CHECK (extra_cost_minor >= 0), currency char(3),
 payment_terms text, delivery_terms text,
 created_by uuid NOT NULL REFERENCES tender_app.app_user(id), created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE (offer_package_id, version), CHECK (currency IS NULL OR currency ~ '^[A-Z]{3}$')
);
CREATE TABLE tender_app.extracted_field (
 id uuid PRIMARY KEY, document_id uuid NOT NULL REFERENCES tender_app.document(id),
 field_name text NOT NULL, value text,
 confidence numeric(4,3) NOT NULL CHECK (confidence BETWEEN 0 AND 1),
 source_location text, source_excerpt text,
 extractor_version text NOT NULL, document_revision integer NOT NULL CHECK (document_revision > 0),
 corrected_by uuid REFERENCES tender_app.app_user(id), corrected_at timestamptz,
 UNIQUE (document_id, document_revision, field_name),
 CHECK (value IS NOT NULL OR confidence = 0)
);
CREATE TABLE tender_app.comparison (
 id uuid PRIMARY KEY, tender_id uuid NOT NULL REFERENCES tender_app.tender(id),
 created_by uuid NOT NULL REFERENCES tender_app.app_user(id),
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE tender_app.comparison_offer (
 comparison_id uuid NOT NULL REFERENCES tender_app.comparison(id),
 offer_version_id uuid NOT NULL REFERENCES tender_app.offer_version(id),
 PRIMARY KEY (comparison_id, offer_version_id)
);
CREATE TABLE tender_app.audit_event (
 id uuid PRIMARY KEY, actor_id uuid NOT NULL REFERENCES tender_app.app_user(id),
 tender_id uuid NOT NULL REFERENCES tender_app.tender(id), document_id uuid REFERENCES tender_app.document(id),
 action text NOT NULL, entity_revision integer,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX document_tender_created_idx ON tender_app.document(tender_id, created_at);
CREATE INDEX offer_package_supplier_idx ON tender_app.offer_package(supplier_id);
CREATE INDEX audit_tender_created_idx ON tender_app.audit_event(tender_id, created_at);
COMMIT;